package org.bukkit.event.player;
import org.bukkit.block.Block; import org.bukkit.entity.Player; import org.bukkit.event.Cancellable; import org.bukkit.event.HandlerList;
public final class PlayerBedEnterEvent extends PlayerEvent implements Cancellable { private final Block bed; private boolean cancelled; private static final HandlerList HANDLERS=new HandlerList(); public PlayerBedEnterEvent(Player p,Block b){super(p);bed=b;} public Block getBed(){return bed;} public boolean isCancelled(){return cancelled;} public void setCancelled(boolean v){cancelled=v;} public HandlerList getHandlers(){return HANDLERS;} public static HandlerList getHandlerList(){return HANDLERS;} }
